import{c as t,Q as a,j as n,m as o}from"./chunks/framework.BqPkuuVc.js";const s="/assets/live-standby-settings.DWHHS2rx.png",r="/assets/live-standby-follow-dialog.H7uTTvhm.png",i="/assets/live-standby-dashboard-chip.CfrBNtRl.png",h="/assets/live-standby-lost-alert.Chvb-pH4.png",d="/assets/live-standby-event-list-following.Dx04Nv5c.png",l="/assets/live-standby-event-list-not-responding.CIo58thB.png",c="/assets/live-standby-takeover-dialog.DEYYEk8X.png",p="/assets/live-standby-taken-over.TKUSFnW6.png",m="/assets/live-standby-handover.CD3V-jst.png",u="/assets/live-standby-stop-following-keep-copy.DMaJ7pov.png",P=JSON.parse('{"title":"Live standby: a second computer ready to take over","description":"","frontmatter":{},"headers":[],"relativePath":"user/running-the-event/live-standby.md","filePath":"user/running-the-event/live-standby.md"}'),g={name:"user/running-the-event/live-standby.md"};function y(v,e,b,f,w,k){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="live-standby-a-second-computer-ready-to-take-over" tabindex="-1">Live standby: a second computer ready to take over <a class="header-anchor" href="#live-standby-a-second-computer-ready-to-take-over" aria-label="Permalink to &quot;Live standby: a second computer ready to take over&quot;">​</a></h1><p><strong>Audience:</strong> Timing operators who want a spare computer at the venue that can carry on the event if the main computer fails.</p><p>A <strong>live standby</strong> is a second computer running meshO Manager on the same network as your main computer. It keeps a copy of the event that is updated as every change is made — every card download, radio punch, entry and edit. If the main computer fails (a dead disk, a flat battery, a laptop knocked off the table), you press <strong>Take over</strong> on the standby, point the stations at it, and carry on. Nothing that was recorded before the failure is lost apart from the last second or so. Elsewhere this is called a hot standby, failover or live replication: see <a href="#other-names-for-this">Other names for this</a>.</p><p>The standby never takes over by itself. A computer that has stopped answering is not always a computer that has stopped running — the network between the two may be what failed — so switching over is always your decision.</p><p>While it follows, the standby only copies. It does not publish results, print, or take radio punches, so having one changes nothing about how the event runs on the main computer.</p><h2 id="before-the-event-set-up-the-pair" tabindex="-1">Before the event: set up the pair <a class="header-anchor" href="#before-the-event-set-up-the-pair" aria-label="Permalink to &quot;Before the event: set up the pair&quot;">​</a></h2><p>You need two computers running meshO Manager on the same network. They should run the same version. A different version that stores events the same way is allowed, and the standby tells you so; one that stores events differently is refused, and the standby says which version to install.</p><h3 id="on-the-main-computer" tabindex="-1">On the main computer <a class="header-anchor" href="#on-the-main-computer" aria-label="Permalink to &quot;On the main computer&quot;">​</a></h3><ol><li>Open <strong>Settings → Live standby</strong>.</li><li>Turn on <strong>Allow a standby computer to follow events on this computer</strong>.</li><li>Note <strong>This computer</strong> (its address) and the <strong>Pairing code</strong>. Anyone with the code can copy the event, so treat it like the manager PIN. <strong>New code</strong> makes a fresh one and disconnects every standby paired with the old one: that is how you un-pair a computer.</li><li>Under <strong>Also copy to the standby</strong>, choose what else the standby takes from this computer: <ul><li><strong>Settings and manager PIN</strong> — so the standby runs the event the way this computer does. The standby keeps its own server, logging, update and video settings.</li><li><strong>HTTPS certificate, so stations already trust the standby</strong> — it is only sent over HTTPS, and the standby uses it after meshO Manager is restarted there.</li><li><strong>Printers and computers</strong> — so a station picks its old entry from the list after a switch-over and gets its printing back.</li><li><strong>Club and competitor registries.</strong></li></ul></li></ol><p><img src="'+s+'" alt="Settings → Live standby on the main computer: the switch that allows a standby, the Pair a standby box with this computer&#39;s address and pairing code and a New code button, the Also copy to the standby choices, and the Standby computers table listing one standby that is in sync."></p><p>The <strong>Standby computers</strong> table at the bottom lists every standby following this computer: the event it follows, whether it is <strong>In sync</strong>, how many changes <strong>behind</strong> it is, or <strong>Lost</strong>, when it was <strong>last heard</strong> from, and when its <strong>copy last moved</strong>.</p><h3 id="on-the-standby-computer" tabindex="-1">On the standby computer <a class="header-anchor" href="#on-the-standby-computer" aria-label="Permalink to &quot;On the standby computer&quot;">​</a></h3><ol><li>On the event list, choose <strong>Live standby</strong>.</li><li>Type the main computer&#39;s address and the pairing code, then <strong>Connect</strong>. The dialog says which computer answered and whether it runs the same version.</li><li>Pick the event under <strong>Event to follow</strong> and choose <strong>Start</strong>. The first copy takes a minute or so; after that every change arrives as it is made.</li></ol><p><img src="'+r+'" alt="The Live standby dialog on the standby computer: the main computer&#39;s address and pairing code filled in, a green box saying it is connected to Finish laptop and runs the same version, City Sprint Championships chosen as the event to follow, and Forest Classic greyed out because this computer already has an event with that id."></p><p>The standby cannot follow an event if it already has an event with the same id — event ids are made from the date, so two computers that each created an event on the same day can clash. The dialog greys such an event out. Use a computer that does not have its own copy of the event.</p><p>A standby follows <strong>every event that is live</strong> on the main computer, not only the one you picked — and any event that goes live there later is picked up by itself, without pairing again. If the afternoon race starts while the morning race is still running, the standby copies both. A take-over takes them all at once: they share the main computer and meshO Prime, and taking over one of two would leave the other on a computer that has stopped, without its radio network.</p><p>While it follows, the standby&#39;s copy is not an event on that computer: it is not listed with its other events, cannot be opened or edited, and is not backed up or published. It is a copy, waiting.</p><blockquote><p><strong>Tip:</strong> Pair the standby before the first start, while the event is quiet, and leave it following all day. You can pair it later, mid-event, too; the first copy just takes a little longer.</p></blockquote><h2 id="during-the-event-what-the-screens-tell-you" tabindex="-1">During the event: what the screens tell you <a class="header-anchor" href="#during-the-event-what-the-screens-tell-you" aria-label="Permalink to &quot;During the event: what the screens tell you&quot;">​</a></h2><h3 id="on-the-main-computer-1" tabindex="-1">On the main computer <a class="header-anchor" href="#on-the-main-computer-1" aria-label="Permalink to &quot;On the main computer&quot;">​</a></h3><p>The foot of the alerts panel, on the right of a live event, shows the standby&#39;s state beside the meshO Prime status, with the live standby icon. With the panel collapsed it is the icon alone; hover over it for the state:</p><ul><li><strong>Standby in sync</strong> — the standby has every change.</li><li><strong>Standby <em>N</em> behind</strong> — changes are on their way to it.</li><li><strong>Standby lost</strong> — the standby has not been heard from for 45 seconds, or it is being heard but its copy has stopped moving.</li><li><strong>No standby</strong> — nothing is following this event.</li></ul><p>Click it for the standby&#39;s name and address, when it was last heard from, when its copy last moved, how many changes it has copied, and the address stations would use if you had to take over.</p><p><img src="'+i+'" alt="The event dashboard on the main computer with the Standby in sync chip clicked open: the standby is Results tent laptop, in sync with nothing behind, last heard and copy last moved 5 seconds ago, 4812 changes copied, and a reminder to press Take over on the standby if this computer fails."></p><p>When a standby of the live event is lost, Manager also raises an alert, because a chip at the foot of a panel is easy to miss: <em>the live standby has stopped copying this event. If this computer fails now, there is no up-to-date copy to take over from.</em> The event carries on here as normal. Check the standby computer and its network; once it is copying again it catches up by itself (or takes a fresh copy first, if it was away a long time), and the alert is withdrawn with a message saying it is copying again.</p><p><img src="'+h+'" alt="The main computer&#39;s dashboard with the alerts panel open, a Standby lost chip at its foot, showing an alert that the live standby Results tent laptop has stopped copying this event."></p><p>No alert is raised for a standby you stop on purpose, nor for an event that has finished.</p><h3 id="on-the-standby-computer-1" tabindex="-1">On the standby computer <a class="header-anchor" href="#on-the-standby-computer-1" aria-label="Permalink to &quot;On the standby computer&quot;">​</a></h3><p>The event list shows a blue <strong>Following</strong> banner with the event&#39;s name, the main computer it is copying, whether it is <strong>In sync</strong>, when the main computer was last heard from, and how many changes have been copied.</p><p><img src="'+d+'" alt="The event list on the standby computer with a blue Following banner: Standby computer, City Sprint Championships, mirrored live from Finish laptop, In sync, last heard 4 seconds ago, 4812 changes copied, with Take over the event and Stop following buttons."></p><p><strong>Catching up</strong> means changes or files are still on their way — after a burst of downloads, or while a large file such as the map or a radio capture arrives a piece at a time over a slow link. It says <strong>In sync</strong> again once everything is in.</p><p>If the main computer goes quiet, the banner turns orange and says <strong>Main computer not responding</strong>, how long it has been quiet, and the time of the last change the copy holds.</p><p><img src="'+l+'" alt="The standby&#39;s banner turned orange: Main computer not responding, nothing heard from Finish laptop for 2 min 17 s, 4812 changes copied, and this copy holds every change up to 10:27:45."></p><p>When the standby follows more than one event, the banner names them all and lists each one with where its copy stands. It leads with whichever needs you most, so one event in sync never hides another that has gone quiet.</p><p>If the main computer&#39;s certificate was copied, the banner also asks you to <strong>restart meshO Manager on this computer before taking over</strong>, so the stations trust it.</p><h2 id="when-the-main-computer-fails-take-over" tabindex="-1">When the main computer fails: take over <a class="header-anchor" href="#when-the-main-computer-fails-take-over" aria-label="Permalink to &quot;When the main computer fails: take over&quot;">​</a></h2><ol><li>On the standby, choose <strong>Take over the event</strong>.</li><li>The dialog says when the main computer was last heard from and what the copy holds, and lists what you will need to do afterwards. If the main computer is in fact still running, it warns you: taking over stops the event there.</li><li>Tick <strong>The main computer cannot carry on with this event</strong> and choose <strong>Take over and resume</strong>.</li></ol><p><img src="'+c+'" alt="The Take over City Sprint Championships dialog: Finish laptop was last heard 2 min 17 s ago, the copy holds every change up to 10:27:45, four steps for after the takeover (move the meshO Prime USB, open the address on every station, choose the card reader again, point SIRAP senders here), and the checkbox The main computer cannot carry on with this event above Take over and resume."></p><p>The standby tells the main computer to stop, if it can still reach it, brings in the changes it had not copied yet, and resumes the event the same way Manager resumes an event after a restart. Live results, Liveresultat and splits printing carry on from the standby. An event that was still being set up on the main computer is taken over as it is, and not started.</p><p>With more than one event followed, the take-over takes every one of them at once, and resumes each one that was running. The dialog names them all and says what each copy holds; afterwards the event list shows them, and each one&#39;s dashboard has its own <strong>Handover</strong> panel. An event that started on the main computer only moments before, whose first copy had not arrived, stays with the main computer.</p><p>You cannot take over while an event is being replayed on the standby: stop the replay first.</p><h3 id="on-the-old-main-computer" tabindex="-1">On the old main computer <a class="header-anchor" href="#on-the-old-main-computer" aria-label="Permalink to &quot;On the old main computer&quot;">​</a></h3><p>If the main computer could not be reached, the standby keeps trying to tell it. When the old main computer comes back, its event pages show that the event now runs on the standby and refuse any change to it, so nothing is recorded twice. It is not offered for resume, and its card on the event list says <strong>Taken over by</strong> the standby.</p><p><img src="'+p+'" alt="On the old main computer, a dialog over the dashboard: This event is now running on Results tent laptop. It took over at 10:24:05; this computer has stopped running the event and refuses changes to it. Stations should use the standby&#39;s address, and the meshO Prime should be moved there. Buttons Back to events and Become the standby."></p><p>Choose <strong>Become the standby</strong> to make the old main computer follow the event from the new one. It takes a fresh copy first. There is no button to take the event back on the old computer; if you want to switch back, take over again from it once it is following.</p><h2 id="what-you-move-by-hand" tabindex="-1">What you move by hand <a class="header-anchor" href="#what-you-move-by-hand" aria-label="Permalink to &quot;What you move by hand&quot;">​</a></h2><p>The event dashboard on the new main computer shows a <strong>Handover</strong> panel with what is left to do:</p><p><img src="'+m+'" alt="The dashboard on the standby after taking over: a green banner saying this computer is now running the event, taken over from Finish laptop, and that Finish laptop will be told as soon as it can be reached; a Handover list with meshO Prime connected and asked to resend its punches, Stations and SIRAP senders; and the address to open on every station with Copy link and Show QR code."></p><ul><li><strong>meshO Prime</strong> — only if the event uses it; otherwise this step is not shown. Prime plugs into the main computer&#39;s USB, so move it to the standby (or plug in a second gateway — never use two at once with the same field units). Field units hold their punches until a gateway is back. As soon as Prime connects to the standby, Manager asks it to resend every punch it holds, which brings in any the old main computer never recorded. Punches the standby already has are recognised and dropped, so nothing appears twice.</li><li><strong>Stations.</strong> Open the standby&#39;s address on every station. The panel shows the link and a QR code. Each station asks for the PIN once and asks which computer it is — pick the same entry it had before.</li><li><strong>SportIdent and EMIT readers.</strong> These are attached to the browser, not the server: choose the reader again on each download station.</li><li><strong>SIRAP senders.</strong> Point them at the standby&#39;s address.</li></ul><p>Choose <strong>Hide handover</strong> when you are done.</p><blockquote><p><strong>Tip:</strong> A router name that you can point at whichever computer is running the event saves re-opening every station: see <a href="./../reference/server-addresses">Reaching the server: name or IP</a>.</p></blockquote><h2 id="what-is-not-carried-over" tabindex="-1">What is not carried over <a class="header-anchor" href="#what-is-not-carried-over" aria-label="Permalink to &quot;What is not carried over&quot;">​</a></h2><ul><li><strong>Print jobs</strong> that were waiting on the main computer, and splits held back for a mis-punch decision.</li><li><strong>A card download that was in flight</strong> at the moment the main computer failed. Read that card again.</li><li>The last second or so of changes.</li></ul><h2 id="stopping-following" tabindex="-1">Stopping following <a class="header-anchor" href="#stopping-following" aria-label="Permalink to &quot;Stopping following&quot;">​</a></h2><p>Choose <strong>Stop following</strong> on the standby&#39;s banner. By default the standby&#39;s copy is discarded and the event carries on on the main computer, which is told the standby left on purpose, so no alert is raised.</p><p>Tick <strong>Keep this computer&#39;s copy as an event</strong> to keep the copy instead. It becomes an ordinary event on the standby computer, as it stood when you stopped — it may lack the main computer&#39;s very latest changes — and it no longer changes. If the event is still running on the main computer, the kept copy is stopped and is not offered for resume, so you never end up with two computers running one event by accident.</p><p><img src="'+u+'" alt="The Stop following dialog with Keep this computer&#39;s copy as an event ticked, explaining that the copy stays in this computer&#39;s events as it is now, no longer changes, and is kept stopped if the event is still running on the main computer."></p><h2 id="if-something-goes-wrong" tabindex="-1">If something goes wrong <a class="header-anchor" href="#if-something-goes-wrong" aria-label="Permalink to &quot;If something goes wrong&quot;">​</a></h2><ul><li><strong>&quot;That pairing code is not the main computer&#39;s&quot;</strong> — check it under <strong>Settings → Live standby</strong> on the main computer. After ten wrong codes the main computer makes that address wait a few minutes.</li><li><strong>&quot;Live standby is turned off on the main computer&quot;</strong> — turn on <strong>Allow a standby computer…</strong> there.</li><li><strong>&quot;The main computer&#39;s certificate is not the one this computer paired with&quot;</strong> — the main computer&#39;s address changed and it made a new certificate. Stop following and pair again.</li><li><strong>The main computer was restarted</strong> — the standby notices and takes a fresh copy by itself.</li><li><strong>The standby shows as lost on a slow or patchy network</strong> — the standby copies in smaller pieces when the link is poor, and catches up when it improves. If it stays lost, check that the standby computer has not gone to sleep.</li></ul><h2 id="other-names-for-this" tabindex="-1">Other names for this <a class="header-anchor" href="#other-names-for-this" aria-label="Permalink to &quot;Other names for this&quot;">​</a></h2><p>If you searched for one of these, this page is what you want (or, for the last two rows, what you don&#39;t).</p><table tabindex="0"><thead><tr><th>If you searched for</th><th>In meshO Manager</th></tr></thead><tbody><tr><td>Hot standby, warm standby, standby server</td><td>The standby computer. It is a hot standby: its copy is up to date to the last second or so.</td></tr><tr><td>Backup computer, backup server, backup timing computer, second results computer, spare laptop, redundant computer</td><td>The standby computer.</td></tr><tr><td>Primary and secondary, master and slave, primary and replica</td><td>The main computer and the standby.</td></tr><tr><td>Failover, automatic failover, manual failover, switch-over</td><td><strong>Take over the event</strong>. Failover is always manual: the standby never takes over by itself.</td></tr><tr><td>Replication, database replication, live replication, mirroring, live mirror</td><td>How the standby&#39;s copy is kept up to date: every change the main computer writes is copied to it as it is made.</td></tr><tr><td>Live sync, live syncing, data sync, real-time sync</td><td>The same: the standby copies every change as it is made.</td></tr><tr><td>Real-time backup, continuous backup</td><td>The standby&#39;s copy, which is ready to run rather than a file to restore. For backup files, see <a href="./../reference/backup-and-restore">Backup and restore</a>.</td></tr><tr><td>High availability, redundancy, disaster recovery, event recovery</td><td>A standby, and taking over when the main computer fails.</td></tr><tr><td>What if the laptop dies, crashes or loses power during an event</td><td><a href="#when-the-main-computer-fails-take-over">Take over</a> on the standby.</td></tr><tr><td>A backup or second computer in MeOS, SportSoftware (OE12) or other timing software</td><td>In meshO Manager, this is the live standby.</td></tr><tr><td>Cloud backup, cloud sync</td><td>Not this. The standby is a computer at the venue, on the event network.</td></tr><tr><td>Several computers on one event, networked stations</td><td>Not this. Download, rego and arena stations all use one server through their browsers; see <a href="./../reference/server-addresses">Reaching the server: name or IP</a>.</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../reference/server-addresses">Reaching the server: name or IP</a></li><li><a href="./../reference/https-and-certificates">HTTPS and certificates</a></li><li><a href="./../reference/backup-and-restore">Backup and restore</a> — the other half of protecting an event</li><li><a href="./connecting-prime-and-radios">Connecting meshO Prime and radios</a>, if you use meshO Prime</li><li><a href="./resolving-issues">Resolving issues on the day</a></li></ul>',64)])])}const S=t(g,[["render",y]]);export{P as __pageData,S as default};
